import json
import tempfile
from collections import defaultdict
from unittest.mock import patch
from batch_sync.dispatcher import dispatch_batch

class Resp:
    def __init__(self, code, headers=None, include_headers=True):
        self.status_code = code
        if include_headers:
            self.headers = headers or {}

calls = defaultdict(int)
sleeps = []
def fake_post(url, json=None, timeout=None):
    cat = json.get('category', 'default')
    calls[cat] += 1
    if cat == 'a' and calls[cat] == 1:
        return Resp(429, {'retry-after': '0'})
    if cat == 'b':
        return Resp(201)
    if cat == 'default' and calls[cat] == 1:
        return Resp(429, include_headers=False)
    return Resp(200)

out = tempfile.NamedTemporaryFile(delete=False).name
with patch('batch_sync.dispatcher.requests.post', side_effect=fake_post):
    with patch('batch_sync.dispatcher.time.sleep', lambda s: sleeps.append(s)):
        summary = dispatch_batch([
            {'event_id': 1, 'category': 'a'},
            {'event_id': 2, 'category': 'b'},
            {'event_id': 3},
        ], max_concurrency=2, summary_path=out)
print(summary)
print(json.load(open(out)))
print(dict(calls), sleeps)
assert summary['total_events'] == 3
assert summary['delivered_count'] == 3
assert summary['failed_count'] == 0
assert dict(calls) == {'a': 2, 'b': 1, 'default': 2}
assert sleeps[0] == 0.0
assert 0.0 < sleeps[1] <= 0.5
